"""==============================================================================IOTEC110_OBSERVABILITY_ENGINE.py==============================================================================Observabilidade em Tempo Real=============================================================================="""from __future__ import annotationsimport sqlite3import timefrom pathlib import Pathfrom datetime import datetimeDATABASE = Path("iotec.db")class ObservabilityEngine:    def __init__(self):        self.conn = sqlite3.connect(DATABASE)        self.conn.row_factory = sqlite3.Row    # ==================================================================    def dashboard(self):        agents = self.conn.execute("""            SELECT COUNT(*)            FROM agent_registry        """).fetchone()[0]        online = self.conn.execute("""            SELECT COUNT(*)            FROM agent_registry            WHERE status='ONLINE'        """).fetchone()[0]        missions = self.conn.execute("""            SELECT COUNT(*)            FROM missions        """).fetchone()[0]        pending = self.conn.execute("""            SELECT COUNT(*)            FROM missions            WHERE status='PENDING'        """).fetchone()[0]        running = self.conn.execute("""            SELECT COUNT(*)            FROM missions            WHERE status='RUNNING'        """).fetchone()[0]        finished = self.conn.execute("""            SELECT COUNT(*)            FROM missions            WHERE status='FINISHED'        """).fetchone()[0]        governance = self.conn.execute("""            SELECT COUNT(*)            FROM agent_governance        """).fetchone()[0]        memory = self.conn.execute("""            SELECT COUNT(*)            FROM agent_memory        """).fetchone()[0]        print("\033c", end="")        print("=" * 75)        print("IOTEC LIVE OPERATION CENTER")        print("=" * 75)        print()        print("HORÁRIO........:", datetime.now())        print()        print("AGENTES........:", agents)        print("ONLINE.........:", online)        print()        print("MISSÕES........:", missions)        print("PENDENTES......:", pending)        print("EXECUTANDO.....:", running)        print("FINALIZADAS....:", finished)        print()        print("EVENTOS.........:", governance)        print("MEMÓRIAS........:", memory)        print()        print("=" * 75)    # ==================================================================    def monitor(self):        while True:            self.dashboard()            time.sleep(2)# =============================================================================if __name__ == "__main__":    engine = ObservabilityEngine()    engine.monitor()